'use strict';
(function(root){
const E=AutoOptimizer,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),stats={hp:'HP',mp:'MP',attack:'攻撃力',defense:'守備力',magic:'攻撃魔力',heal:'回復魔力',speed:'すばやさ'},slotNames={weapon:'武器',shield:'盾',head:'頭',body:'体上',legs:'体下',accessory:'アクセサリー',pearl:'心珠'};
const key='walk-auto-v6';function read(){try{return E.validate(JSON.parse(localStorage.getItem(key))||{});}catch{return E.defaults();}}
const input=(name,label,v,min=0,max=100000,step=1)=>`<label>${label}<input name="${name}" type="number" value="${v}" min="${min}" max="${max}" step="${step}" required></label>`;
function run(m,p,s){return new Promise((resolve,reject)=>{if(typeof Worker==='undefined'){try{resolve(E.solve(m,p,s));}catch(e){reject(e);}return;}let w;try{w=new Worker('workers/auto.js');w.onmessage=e=>{w.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data.result);};w.onerror=()=>{w.terminate();reject(Error('計算ワーカーを起動できませんでした。Web版で開き直してください。'));};w.postMessage({master:m,profile:p,settings:s});}catch(e){w?.terminate();try{resolve(E.solve(m,p,s));}catch(e){reject(e);}}});}
function render({target,master,profile}){let s=read(),result=null;const mapping=CombatRules.assignments(profile,CombatRules.articleRoles).find(a=>a[0]===0)||[0,1,2,3];
 target.innerHTML=`<div class="row spread"><h2>アギロゴス 火力から自動最適化</h2><span class="badge pending">自動計算 0.18</span></div><p>ダメージの入力は不要です。記事の2ターン手順に必要な武器・継承・二刀流を満たす候補から、防具・アクセサリー・心珠・こころ4枠まで選び、各攻撃の火力を計算して比較します。</p><div class="notice">収録装備内での近似探索です。実機の基礎能力を未登録の場合は仮の職業能力を使います。仮値を含む結果を確定討伐として扱いません。</div><form id="auto-form"><div class="details-grid"><section class="panel"><h3>攻略条件</h3>${input('hp','開始時の敵残HP',s.hp,1,1e8)}${input('maxHP','敵最大HP（シールド判定）',s.maxHP,1,1e8)}${input('defense','敵守備力（未確認の初期値）',s.defense)}<label>有効な領域<select name="domain"><option value="roto" ${s.domain==='roto'?'selected':''}>ロトの伝説</option><option value="brave" ${s.domain==='brave'?'selected':''}>ブレイブゾーン</option><option value="none" ${s.domain==='none'?'selected':''}>領域なし</option></select></label><p class="muted">領域は同時に重ねません。実際の発動・上書き順に合わせて選びます。確率ゾーンと偶発的な根絶やしマインドは下限に加算しません。</p></section><section class="panel"><h3>探索の制約</h3><label><input name="enforceOrder" type="checkbox" ${s.enforceOrder?'checked':''}> 指定の味方速度順を満たす候補に絞る</label><label><input name="includeEstimated" type="checkbox" ${s.includeEstimated?'checked':''}> 仮の性能を含む収録品も候補にする</label>${input('minHP','各キャラの最低HP（0＝指定なし）',s.minHP)}<div class="fields">${CombatRules.roles.map((r,i)=>input('minSpeed'+i,r.name+'の最低すばやさ',s.minSpeeds[i])).join('')}</div><p class="muted">速度順は守り人・大魔道士→大神官→魔人。並び順は大神官→魔人→守り人→大魔道士です。敵の割り込みと耐久は別途確認が必要です。</p></section></div><details class="panel sub"><summary>基礎能力を実データで登録する</summary><p>装備・こころを外した状態の能力を入力します。永続効果・熟練度・こころ道などの個人差を含めてください。「この基礎能力を使う」を入れたキャラだけ置き換えます。装備込みの表示攻撃力を入れると二重加算になります。</p><div class="character-grid">${CombatRules.articleRoles.map((r,i)=>{const member=mapping[i],b=E.baseFor(master,profile,member,r.job,s),v=b.value||{stats:{},cost:0},custom=!!s.baseOverrides[member+':'+r.job];return `<section class="loadout"><h3>${r.name} / ${esc(profile.characters[member]?.name)}</h3><p>Lv.${profile.characters[member]?.levels[r.job]||0} ${b.estimated?'現在は仮の職業能力':'登録した基礎能力'}</p><label><input type="checkbox" name="baseUse${i}" ${custom?'checked':''}> この基礎能力を使う</label>${Object.entries(stats).map(([k,label])=>input('base'+i+'-'+k,label,v.stats[k]||0)).join('')}${input('base'+i+'-cost','こころ基礎コスト上限',v.cost,0,10000)}</section>`;}).join('')}</div></details><details class="panel sub"><summary>効果・こころ道の数値条件</summary><div class="fields">${input('guardTurns','聖なる防壁の残りターン（仮）',s.guardTurns,1,20)}${input('echoRate','やまびこの威力係数',s.echoRate,.5,.8,.1)}${input('majinPathCritical','魔人こころ道の追加会心倍率',s.majinPathCritical,0,.5,.1)}${input('mindExtra','確定している系統効果の追加増幅',s.mindExtra,0,2,.1)}</div><p class="muted">会心倍率は基本1.6＋魔人の痛恨0.5＋こころ道＋装備補正。根絶やしは系統効果値を+300%増幅します。乱数範囲やロンドの攻魔複合式には検証前の仮定が残ります。</p></details><div class="row padded"><button id="auto-solve" type="submit" class="primary">所持品から火力と装備を自動計算 →</button><button id="auto-export" type="button" disabled>計算結果をJSONで保存</button></div><p id="auto-status" role="status"></p></form><section id="auto-results"></section>`;
 const form=target.querySelector('#auto-form'),status=target.querySelector('#auto-status'),output=target.querySelector('#auto-results'),button=target.querySelector('#auto-solve'),exportButton=target.querySelector('#auto-export');
 function collect(){const fd=new FormData(form),next={...s,baseOverrides:{}};for(const k of ['hp','maxHP','defense','minHP','guardTurns','echoRate','majinPathCritical','mindExtra'])next[k]=Number(fd.get(k));next.domain=fd.get('domain');for(const k of ['enforceOrder','includeEstimated'])next[k]=fd.has(k);next.minSpeeds=[0,1,2,3].map(i=>Number(fd.get('minSpeed'+i)));CombatRules.articleRoles.forEach((r,i)=>{if(fd.has('baseUse'+i))next.baseOverrides[mapping[i]+':'+r.job]={stats:Object.fromEntries(Object.keys(stats).map(k=>[k,Number(fd.get('base'+i+'-'+k))])),cost:Number(fd.get('base'+i+'-cost'))};});return E.validate(next);}
 form.onchange=()=>{result=null;exportButton.disabled=true;output.innerHTML='<p class="notice">条件が変わりました。再計算してください。</p>';};
 form.onsubmit=async e=>{e.preventDefault();if(button.disabled)return;try{s=collect();localStorage.setItem(key,JSON.stringify(s));button.disabled=true;status.textContent='4人分の装備・こころと攻撃手順を計算中…';const snapshot=JSON.stringify(s),calculated=await run(master,profile,s);if(button!==target.querySelector('#auto-solve'))return;if(JSON.stringify(collect())!==snapshot){status.textContent='条件が変わったため再計算してください。';return;}result=calculated;show();exportButton.disabled=false;status.textContent='計算完了。条件をブラウザに保存しました。';}catch(error){status.textContent='計算できません：'+error.message;}finally{button.disabled=false;}};
 function show(){if(result.status!=='ok'){output.innerHTML='<div class="panel"><h3>条件を満たす候補が見つかりません</h3><ul>'+result.issues.map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul></div>';return;}output.innerHTML=`<h2 class="padded">自動計算の候補</h2><p>${result.nodes.toLocaleString()}組を結合検査。防具・心珠・こころ4枠を選定し、操作順で下限・上限を再計算しました。大域最適・実機の安定討伐を保証する判定ではありません。</p>${result.results.map((t,n)=>`<article class="panel sub"><h3>候補 ${n+1} / ${t.lower.killed?'計算下限でHP0':t.upper.killed?'上限ではHP0・下限は不足':'探索した候補ではHP未到達'}</h3><p class="${t.estimated?'notice':'muted'}">${t.estimated?'仮の職業能力または装備性能を含む参考値です。':'登録済み能力・確認済み性能の候補です。'} 敵行動と生存は未検証です。</p><div class="row"><span class="pill">下限時の残HP ${t.lower.enemy.hp.toLocaleString()}</span><span class="pill">上限時の残HP ${t.upper.enemy.hp.toLocaleString()}</span><span class="pill">下限で破壊 ${t.lower.enemy.broken} / 4枚</span></div>${t.lower.issues.length?'<ul class="errorlist">'+t.lower.issues.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':''}<div class="character-grid">${t.positions.map(i=>{const b=t.builds[i];return `<section class="loadout"><h3>${b.jobName} / ${esc(b.name)}</h3><p>Lv.${b.level} / すばやさ ${b.stats.speed}</p><dl>${Object.entries(slotNames).map(([slot,label])=>'<dt>'+label+'</dt><dd>'+(b.items.filter(x=>x.slot===slot).map(x=>esc(x.name)+(x.limitBreak!==undefined?' '+x.limitBreak+'凸':'')).join('<br>')||'なし')+'</dd>').join('')}<dt>継承</dt><dd>${esc(b.inherit?.name||'なし')}</dd><dt>左手</dt><dd>${esc(b.left?.name||'なし')}</dd><dt>こころ4枠</dt><dd>${b.hearts.map(h=>'枠'+(h.heartSlot+1)+' '+esc(h.name)+' ×'+h.factor).join('<br>')}</dd></dl><p>コスト ${b.cost} / ${b.baseCost+b.costBonus}</p><div class="statgrid">${Object.entries(stats).map(([k,v])=>'<span>'+v+' '+b.stats[k]+'</span>').join('')}</div></section>`;}).join('')}</div><h3>操作順のダメージ</h3><ol class="timeline">${t.lower.steps.map(step=>{const trace=t.lower.traces.filter(x=>x.turn===step.turn&&x.role===step.actor&&x.skill===step.skill);return `<li><strong>${step.turn}T ${step.actor==='enemy'?'アギロゴス':t.builds[step.actor].jobName} → ${esc(CombatRules.skill(step.skill)?.name||step.skill)}</strong><br>${esc(step.detail)}${step.hit?'<br>制限前 '+step.hit.raw.toLocaleString()+' / HP反映 '+step.hit.applied.toLocaleString()+' / ブレイク '+step.hit.broken+'枚':''}<br><span class="muted">敵残HP ${step.hp.toLocaleString()}</span></li>`;}).join('')}</ol><details><summary>各攻撃の式・選択属性・補正を確認</summary>${t.lower.traces.map(x=>`<p>${x.turn}T ${t.builds[x.role].jobName} ${esc(CombatRules.skill(x.skill).name)} ${x.cast+1}発目：${x.min.toLocaleString()}〜${x.max.toLocaleString()} / ${x.element} / 基礎${x.base} / 攻撃${x.stages??0}段階 / 系統補正+${Math.round(x.raceBonus*100)}% / 種別倍率${x.typeRate.toFixed(3)}<br>${esc(x.formula)}</p>`).join('')}</details><p>味方速度順：${t.order.map(o=>CombatRules.roles[o.first].name+'→'+CombatRules.roles[o.second].name+' '+(o.certain?'設定した乱数範囲で成立':'名目順のみ・保証なし')).join(' / ')}</p></article>`).join('')}<details class="notice"><summary>計算の範囲と残る仮定</summary><ul>${result.limitations.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p>参考：<a href="https://walk.dragonquest.jp/web/help/" target="_blank" rel="noreferrer">公式の二刀流・継承仕様</a> / <a href="https://9db.jp/dqwalk/data/17200" target="_blank" rel="noreferrer">会心の検証</a> / <a href="https://9db.jp/dqwalk/data/13412?p=14" target="_blank" rel="noreferrer">ざざん波の検証</a></p></details>`;}
 exportButton.onclick=()=>{if(!result)return;const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({settings:s,result},null,2)],{type:'application/json'}));a.href=url;a.download='walk-auto-result-0.6.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
}
root.AutoUI={render,read};
})(typeof window==='undefined'?globalThis:window);
